
USE [olist_dwh];
GO

--=========================================================================
-- create the payment type dimension table
-- i am creating the payment type dimension in the gold schema.
-- payment_type_key will be the surrogate key generated by sql server.
-- payment_type will identify each payment method used by customers.
--=========================================================================

IF OBJECT_ID('[gold].[dim_payment_type]', 'U') IS NULL
BEGIN
    CREATE TABLE [gold].[dim_payment_type]
    (
        payment_type_key INT IDENTITY(1,1) NOT NULL,
        payment_type VARCHAR(50) NOT NULL,

        CONSTRAINT PK_dim_payment_type
            PRIMARY KEY (payment_type_key)
    );
END;
GO

--=========================================================================
-- create a unique index for the payment type business key
-- i am ensuring that each payment type can only appear once
-- in the dimension.
-- this prevents duplicate payment type records from being inserted.
--=========================================================================

IF NOT EXISTS
(
    SELECT 1
    FROM sys.indexes
    WHERE name = 'UX_dim_payment_type'
      AND object_id = OBJECT_ID('[gold].[dim_payment_type]')
)
BEGIN
    CREATE UNIQUE NONCLUSTERED INDEX UX_dim_payment_type
    ON [gold].[dim_payment_type] (payment_type);
END;
GO

--=========================================================================
-- insert the unknown payment type record
-- i am inserting an unknown payment type with payment_type_key = -1.
-- this record will also represent source records where payment_type
-- was standardised to Unknown in the silver layer.
-- identity_insert allows me to insert -1 manually.
-- the if not exists check prevents duplicate unknown records.
--=========================================================================

IF NOT EXISTS
(
    SELECT 1
    FROM [gold].[dim_payment_type]
    WHERE payment_type_key = -1
)
BEGIN
    SET IDENTITY_INSERT [gold].[dim_payment_type] ON;

    INSERT INTO [gold].[dim_payment_type]
    (
        payment_type_key,
        payment_type
    )
    VALUES
    (
        -1,
        'Unknown'
    );

    SET IDENTITY_INSERT [gold].[dim_payment_type] OFF;
END;
GO
